git apply <<'PATCH'
diff --git a/test/ranges-test.cc b/test/ranges-test.cc
--- a/test/ranges-test.cc
+++ b/test/ranges-test.cc
@@ -15,6 +15,10 @@
 #include <string>
 #include <vector>

+#if FMT_CPLUSPLUS >= 202002L && FMT_HAS_INCLUDE(<ranges>)
+#  include <ranges>
+#endif
+
 #include "gtest/gtest.h"
@@ -428,3 +432,64 @@
 TEST(ranges_test, vector_char) {
   EXPECT_EQ(fmt::format("{}", std::vector<char>{'a', 'b'}), "['a', 'b']");
 }
+
+TEST(ranges_test, nested_char_range) {
+  auto v = std::vector<std::vector<char>>{{'a'}, {'b', '-', 'c'}, {'\n'}, {}};
+  EXPECT_EQ(fmt::format("{}", v), "[['a'], ['b', '-', 'c'], ['\\n'], []]");
+  EXPECT_EQ(fmt::format("{:n}", v), "['a'], ['b', '-', 'c'], ['\\n'], []");
+  EXPECT_EQ(fmt::format("{::}", v), "[['a'], ['b', '-', 'c'], ['\\n'], []]");
+  EXPECT_EQ(fmt::format("{:::}", v), "[[a], [b, -, c], [\n], []]");
+}
+
+TEST(ranges_test, nested_string_range) {
+  auto v = std::vector<std::vector<std::string>>{{"a", "b\nc"}, {}};
+  EXPECT_EQ(fmt::format("{}", v), "[[\"a\", \"b\\nc\"], []]");
+  EXPECT_EQ(fmt::format("{:::}", v), "[[a, b\nc], []]");
+}
+
+#ifdef __cpp_lib_ranges
+TEST(ranges_test, format_split_view) {
+  auto line = std::string("a,b-c,d-e,f");
+  EXPECT_EQ(fmt::format("{}", line | std::views::split(',')),
+            "[['a'], ['b', '-', 'c'], ['d', '-', 'e'], ['f']]");
+}
+
+struct non_const_char_range {
+  std::string_view sv;
+
+  template <std::ranges::range R>
+  explicit non_const_char_range(R&& r)
+      : sv(std::ranges::data(r), std::ranges::size(r)) {}
+
+  auto begin() { return sv.begin(); }
+  auto end() { return sv.end(); }
+};
+
+TEST(ranges_test, format_non_const_char_range) {
+  auto line = std::string("a,b-c,d-e,f");
+  auto parts = line | std::views::split(',') |
+               std::views::transform(
+                   [](auto part) { return non_const_char_range(part); });
+  EXPECT_EQ(fmt::format("{}", parts),
+            "[['a'], ['b', '-', 'c'], ['d', '-', 'e'], ['f']]");
+  EXPECT_FALSE((fmt::is_formattable<const non_const_char_range&>::value));
+
+  auto empty_parts = std::string(",a,,") | std::views::split(',') |
+                     std::views::transform(
+                         [](auto part) { return non_const_char_range(part); });
+  EXPECT_EQ(fmt::format("{}", empty_parts), "[[], ['a'], [], []]");
+}
+
+TEST(ranges_test, format_nested_split_view) {
+  auto line = std::string("a,b-c,d-e,f");
+  auto parts = line | std::views::split(',') |
+               std::views::transform(std::views::split('-'));
+  EXPECT_EQ(fmt::format("{}", parts),
+            "[[['a']], [['b'], ['c']], [['d'], ['e']], [['f']]]");
+}
+#endif
